from taf.fdsw.rc.interfaces.FDSW22B.fdsw import FDSW22B


class FDSW23A(FDSW22B):
    VERSION_NAME = 'FDSW23A'
    _client = None

    def __init__(self, ip_address, port, username, password, secure=True):
        super(FDSW23A, self).__init__(ip_address=ip_address, port=port, username=username, password=password,
                                      secure=secure)
